import { plant, R, LF, FF, FIX, t } from './_helpers.mjs';

// Third batch of herbs: the Finnish herb tradition, including wild herbs,
// trees and berries gathered for food, tea and traditional remedies.
// Cultivation figures are cross-checked against the Finnish cultivation
// guides referenced in the Yrttitarha database (Mikkeli trials), where
// available. Uses are added separately in uses.mjs.

const SRC = 'Growing figures cross-checked with Finnish herb cultivation guides (Yrttitarha).';

/** A herb that is grown in gardens. */
const herb = (id, sci, common, spec) =>
  plant(id, sci, common, { category: 'herb', sourceNote: SRC, ...spec, tags: ['herb', ...(spec.tags ?? [])] });

/** A plant mostly gathered from the wild (can often be grown, but rarely is). */
const wild = (id, sci, common, spec) =>
  plant(id, sci, common, { sourceNote: SRC, conf: 'low', ...spec, tags: ['wild-harvest', ...(spec.tags ?? [])] });

const zones = (fiMax, usdaMin, usdaMax) => ({ finnishZones: R(1, fiMax), usdaZones: R(usdaMin, usdaMax) });

